# H kodu -> GHS piktogramı eşlemesi (SEA/CLP Ek I). app.py'deki önizleme
# eşlemesiyle aynı kaynak; tek yerde tutulur ki Excel çıktısı ile ekran
# önizlemesi ASLA ayrışmasın.
H_KODU_GHS = {
    "H200": "GHS01", "H201": "GHS01", "H202": "GHS01", "H203": "GHS01",
    "H204": "GHS01", "H240": "GHS01", "H241": "GHS01",
    "H220": "GHS02", "H221": "GHS02", "H222": "GHS02", "H223": "GHS02",
    "H224": "GHS02", "H225": "GHS02", "H226": "GHS02", "H228": "GHS02",
    "H242": "GHS02", "H250": "GHS02", "H251": "GHS02", "H252": "GHS02",
    "H260": "GHS02", "H261": "GHS02",
    "H270": "GHS03", "H271": "GHS03", "H272": "GHS03",
    "H280": "GHS04", "H281": "GHS04",
    "H290": "GHS05", "H314": "GHS05", "H318": "GHS05",
    "H300": "GHS06", "H301": "GHS06", "H310": "GHS06", "H311": "GHS06",
    "H330": "GHS06", "H331": "GHS06",
    "H302": "GHS07", "H312": "GHS07", "H315": "GHS07", "H317": "GHS07",
    "H319": "GHS07", "H332": "GHS07", "H335": "GHS07", "H336": "GHS07",
    "H420": "GHS07",
    "H304": "GHS08", "H334": "GHS08", "H340": "GHS08", "H341": "GHS08",
    "H350": "GHS08", "H351": "GHS08", "H360": "GHS08", "H361": "GHS08",
    "H370": "GHS08", "H371": "GHS08", "H372": "GHS08", "H373": "GHS08",
    "H400": "GHS09", "H410": "GHS09", "H411": "GHS09",
}


def _adr_kod_normalize(kod) -> str:
    """'Sınıf 3', '3.', '7X', '7E' gibi girişleri sözlük anahtarına indirger.
    (msds-ozetleyici'deki _adr_norm_kod ile aynı davranış.)"""
    s = str(kod or "").upper().replace("SINIF", "").replace("CLASS", "").strip().strip(".")
    if s.startswith("7"):
        return "7"
    return s


def adr_etiket_kodlari(etiket_alani) -> list:
    """Tablo A 'Etiketler' hücresini ayrı etiket kodlarına böler.
    Hücre '2.2', '3+6.1', '8\n6.1' gibi biçimlerde gelebilir."""
    if not etiket_alani:
        return []
    parcalar = re.split(r"[+,/\n\s]+", str(etiket_alani))
    kodlar = []
    for p in parcalar:
        k = _adr_kod_normalize(p)
        if k and k in ADR_ETIKET_PNG and k not in kodlar:
            kodlar.append(k)
    return kodlar


def ghs_kodlari(h_kodlari) -> list:
    """H kodu listesinden/metninden GHS piktogram kodlarını çıkarır
    (tekrarlar elenir, sıra korunur)."""
    if not h_kodlari:
        return []
    if isinstance(h_kodlari, (list, tuple)):
        ham = " ".join(str(x) for x in h_kodlari)
    else:
        ham = str(h_kodlari)
    kodlar = []
    for h in re.findall(r"H\d{3}", ham.upper()):
        g = H_KODU_GHS.get(h)
        if g and g in GHS_ETIKET_PNG and g not in kodlar:
            kodlar.append(g)
    return kodlar


def png_akisi(kod: str):
    """Verilen ADR veya GHS kodu için PNG bayt akışı (BytesIO) döner.
    openpyxl.drawing.image.Image doğrudan bu akışı kabul eder.
    Kod tanınmıyorsa None döner."""
    b64 = ADR_ETIKET_PNG.get(kod) or GHS_ETIKET_PNG.get(kod)
    if not b64:
        return None
    return io.BytesIO(base64.b64decode(b64))
